"""Load a JSON config file, falling back to built-in defaults when absent."""

from __future__ import annotations

import json
import logging
from pathlib import Path
from typing import Any, Mapping

logger = logging.getLogger(__name__)

DEFAULTS: dict[str, Any] = {
    "host": "127.0.0.1",
    "port": 8080,
    "debug": False,
    "log_level": "INFO",
    "timeout_seconds": 30,
}


class ConfigError(Exception):
    """Raised when a config file exists but cannot be parsed."""


def _merge(base: Mapping[str, Any], override: Mapping[str, Any]) -> dict[str, Any]:
    """Recursively merge override into base, returning a new dict."""
    merged = dict(base)
    for key, value in override.items():
        current = merged.get(key)
        if isinstance(current, Mapping) and isinstance(value, Mapping):
            merged[key] = _merge(current, value)
        else:
            merged[key] = value
    return merged


def load_config(
    path: str | Path,
    defaults: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Return the config at `path` merged over `defaults`.

    A missing file is not an error: the defaults are returned unchanged. A file
    that exists but holds invalid JSON, or JSON that is not an object, raises
    ConfigError -- that is a mistake worth surfacing, not one to paper over.
    """
    base = DEFAULTS if defaults is None else defaults
    path = Path(path)

    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        logger.info("No config at %s; using defaults", path)
        return dict(base)
    except OSError as exc:
        raise ConfigError(f"Could not read {path}: {exc}") from exc

    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ConfigError(f"Invalid JSON in {path}: {exc}") from exc

    if not isinstance(data, dict):
        raise ConfigError(f"Expected a JSON object in {path}, got {type(data).__name__}")

    return _merge(base, data)
